            s0 = kc.mma(aq0, bk00, s0, MMAShape.M16N8K16);
            HalfFloat[] bk01 = kc.mmaLoadB(kT, 16, 256);
            s1 = kc.mma(aq0, bk01, s1, MMAShape.M16N8K16);
            HalfFloat[] bk02 = kc.mmaLoadB(kT, 16, 512);
            s2 = kc.mma(aq0, bk02, s2, MMAShape.M16N8K16);
            HalfFloat[] bk03 = kc.mmaLoadB(kT, 16, 768);
            s3 = kc.mma(aq0, bk03, s3, MMAShape.M16N8K16);
            HalfFloat[] bk04 = kc.mmaLoadB(kT, 16, 1024);
            s4 = kc.mma(aq0, bk04, s4, MMAShape.M16N8K16);
            HalfFloat[] bk05 = kc.mmaLoadB(kT, 16, 1280);
            s5 = kc.mma(aq0, bk05, s5, MMAShape.M16N8K16);
            HalfFloat[] bk06 = kc.mmaLoadB(kT, 16, 1536);
            s6 = kc.mma(aq0, bk06, s6, MMAShape.M16N8K16);
            HalfFloat[] bk07 = kc.mmaLoadB(kT, 16, 1792);
            s7 = kc.mma(aq0, bk07, s7, MMAShape.M16N8K16);
            HalfFloat[] bk10 = kc.mmaLoadB(kT, 16, 2048);
            s0 = kc.mma(aq1, bk10, s0, MMAShape.M16N8K16);
            HalfFloat[] bk11 = kc.mmaLoadB(kT, 16, 2304);
            s1 = kc.mma(aq1, bk11, s1, MMAShape.M16N8K16);
            HalfFloat[] bk12 = kc.mmaLoadB(kT, 16, 2560);
            s2 = kc.mma(aq1, bk12, s2, MMAShape.M16N8K16);
            HalfFloat[] bk13 = kc.mmaLoadB(kT, 16, 2816);
            s3 = kc.mma(aq1, bk13, s3, MMAShape.M16N8K16);
            HalfFloat[] bk14 = kc.mmaLoadB(kT, 16, 3072);
            s4 = kc.mma(aq1, bk14, s4, MMAShape.M16N8K16);
            HalfFloat[] bk15 = kc.mmaLoadB(kT, 16, 3328);
            s5 = kc.mma(aq1, bk15, s5, MMAShape.M16N8K16);
            HalfFloat[] bk16 = kc.mmaLoadB(kT, 16, 3584);
            s6 = kc.mma(aq1, bk16, s6, MMAShape.M16N8K16);
            HalfFloat[] bk17 = kc.mmaLoadB(kT, 16, 3840);
            s7 = kc.mma(aq1, bk17, s7, MMAShape.M16N8K16);
