            pT[((warp * 4 + 0) * 16 + (lane >> 2) + 8) * 8 + 0 + quad] = pack(p02, p03);
            pT[((warp * 4 + 0) * 16 + (lane >> 2)) * 8 + 4 + quad] = pack(p10, p11);
            pT[((warp * 4 + 0) * 16 + (lane >> 2) + 8) * 8 + 4 + quad] = pack(p12, p13);
