            HalfFloat[] bv01 = kc.mmaLoadB(vT, 16, 256);
            f1 = kc.mma(ap0, bv01, f1, MMAShape.M16N8K16);
            HalfFloat[] bv11 = kc.mmaLoadB(vT, 16, 1280);
            f1 = kc.mma(ap1, bv11, f1, MMAShape.M16N8K16);
            HalfFloat[] bv21 = kc.mmaLoadB(vT, 16, 2304);
            f1 = kc.mma(ap2, bv21, f1, MMAShape.M16N8K16);
            HalfFloat[] bv31 = kc.mmaLoadB(vT, 16, 3328);
            f1 = kc.mma(ap3, bv31, f1, MMAShape.M16N8K16);
            o10 = o10 * al0 + f1[0];
            o11 = o11 * al0 + f1[1];
            o12 = o12 * al1 + f1[2];
            o13 = o13 * al1 + f1[3];
