            HalfFloat[] bv12 = kc.mmaLoadB(vT, 16, 1536);
            f2 = kc.mma(ap1, bv12, f2, MMAShape.M16N8K16);
            HalfFloat[] bv22 = kc.mmaLoadB(vT, 16, 2560);
            f2 = kc.mma(ap2, bv22, f2, MMAShape.M16N8K16);
            HalfFloat[] bv32 = kc.mmaLoadB(vT, 16, 3584);
            f2 = kc.mma(ap3, bv32, f2, MMAShape.M16N8K16);
            o20 = o20 * al0 + f2[0];
            o21 = o21 * al0 + f2[1];
            o22 = o22 * al1 + f2[2];
            o23 = o23 * al1 + f2[3];
            float[] f3 = kc.mmaFragment(0.0f);
            HalfFloat[] bv03 = kc.mmaLoadB(vT, 16, 768);
            f3 = kc.mma(ap0, bv03, f3, MMAShape.M16N8K16);
            HalfFloat[] bv13 = kc.mmaLoadB(vT, 16, 1792);
            f3 = kc.mma(ap1, bv13, f3, MMAShape.M16N8K16);
