        float l0 = ls[r0];
        float l1 = ls[r1];
        float e0 = dl[r0];
        float e1 = dl[r1];
        float[] dq0 = kc.mmaFragment(0.0f);
        float[] dq1 = kc.mmaFragment(0.0f);
        float[] dq2 = kc.mmaFragment(0.0f);
        float[] dq3 = kc.mmaFragment(0.0f);
        float[] dq4 = kc.mmaFragment(0.0f);
        float[] dq5 = kc.mmaFragment(0.0f);
        float[] dq6 = kc.mmaFragment(0.0f);
